// Code generated by porting packages/cli/src/help.ts (data port, see docs/scope-go-cli.md §4).
//
// parlay CLI usage and per-command help text.
package help

import (
	"fmt"
	"strings"

	"github.com/trillium/parlay/tools/cli/internal/config"
)

// usageTemplate is USAGE with the live server URL replaced by a {{SERVER}} placeholder —
// Go has no import-time SERVER snapshot, so Usage(server) substitutes it per call.
const usageTemplate = "parlay — talk to a Parlay chat server (current target: {{SERVER}})\n\nUsage:\n  parlay                          Panel/fleet snapshot: subscribers, agents, last 3 messages\n  parlay status <verb> [--key <slug>] <note...>   Emit a keyed agent→supervisor status line (fold §3.6)\n  parlay status                   Read THIS agent's keyed status file\n  parlay subscribers [--full]     Connection counts (--full: raw JSON)\n  parlay agents [--full]          List registered agents (--full: raw JSON)\n  parlay agent-down <id>          Deregister any agent channel (general-purpose; not just variants)\n  parlay shutdown <id>             Graceful retirement: end local listener + idempotent server unregister (task-35ww)\n  parlay remote                   Show the current server URL + its source (env/config/default)\n  parlay remote set <url>         Persist a default server URL (~/.parlay/config.json; survives shells)\n  parlay remote clear             Remove the persisted default server URL\n  parlay defaults                 Show persisted defaults (server URL + spawn account)\n  parlay defaults set account <n> Persist a default ccjuggler account for 'parlay spawn'\n  parlay defaults clear account   Remove the persisted spawn account\n  parlay spawn-account [set <n>|clear]   Legacy config-file-only view of the default spawn account (prefer 'defaults')\n  parlay nickname <nick...>       Set voice nicknames for THIS agent (picker/voice channel-switch)\n  parlay nickname --agent <id> <nick...>   Set nicknames for a named agent (--clear to remove)\n  parlay send                     List agents you can message\n  parlay send --<agent-id> <text> Send attributed message to that agent's channel\n  parlay say <text...>            Reply to YOUR OWN channel (spawned agents; identity from PARLAY_AGENT_ID)\n  parlay reply <text...>          Alias for 'say' (bare 'reply' wraps this)\n  parlay scratchpad [<note>]      Your durable task notes; no args = read (bare 'scratchpad' wraps this)\n  parlay identity [<fact>]        Your durable self-knowledge; no args = read (bare 'identity' wraps this)\n  parlay drawdown [N]             Draft a handoff prompt from the last N messages (default 20) — portable, works without a handoff store\n  parlay idle [hours]             Signal 'paused' with a resume time, then print how to come back (default 1h)\n  parlay alert <text...>          Broadcast an alert to all pollers + agents\n  parlay alert --agent <id> <text...>   Alert one agent channel\n  parlay history [N] [--full]     Last N messages, truncated (default 20; --full: untruncated)\n  parlay monitor --agent <id> [--notify-safe]   Relay-backed enroll + stream — emits CHAT_MSG lines (for Monitor{})\n  parlay monitor --legacy-poll [--agent <id>]   Old independent poll loop (no relay)\n  parlay monitor --reap [--apply]   List channel readers whose launcher is gone (--apply kills them)\n  parlay listen --agent <id> [--name <name>] [--caps <json>] [--account <n>] [--notify-safe]   One-call self-enroll: register + announce + monitor (alias: agent-up)\n  parlay stats                    Message memory/complexity stats (count, sizes, ages, images)\n  parlay health                   Server vitals: reachability, subscribers/memory, eval-engine (optional)\n  parlay doctor [--json]           THIS agent's self-diagnosis: PASS/WARN/FAIL + fix per check (--json: schema parlay.doctor/v1)\n  parlay heal <check-id>|--all    Guarded self-heal of whitelisted mechanical fixes, re-verify each\n  parlay context-check <pct>      Rotation advisory: OK, or ROTATE (exit 3) at/above the threshold (default 85%)\n  parlay robots-watch [--once]    Event poll-daemon: robots-created→mechanic-dispatch, request-closed→notify\n  parlay robots-tail [--once]     Push fast-path: tail robots events.jsonl → mechanic-dispatch (~1s, poll stays fallback)\n  parlay inbox-tail [--once]      Push fast-path: tail inbox events.jsonl → inbox-dispatch (~1s, poll stays fallback)\n  parlay mechanic off|on|status   Pause / resume auto-mechanic dispatch (kill switch for robots→mechanic spawner)\n  parlay inbox-dispatch off|on|status   Pause / resume auto-inbox dispatch (independent of 'mechanic')\n  parlay eval serve [--addr A] [--push-url U]   Run the compiled eval-engine HTTP service (voice layer; foreground)\n  parlay launch                   List known agents: live / ghost (registered, nothing listening) / offline\n  parlay launch <id>              Spawn an offline agent via the in-process spawn pipeline (uses identity frontmatter)\n  parlay spawn <id> <name> <color> [<prompt>] [flags]   Spawn a new agent (in-process pipeline; task-42qot)\n  parlay spawn-watchdog <id> --launcher <l> --server <url>   Post-launch liveness watch (armed by 'parlay spawn'; rarely run by hand)\n  parlay reset [flags]            Clean self-restart for a persistent agent (alias: reincarnate)\n  parlay subprocess-spawn <id> [flags]   Start a detached herdr-free subprocess session (see also: spawn --subprocess)\n  parlay subprocess-stop <id>     Stop a subprocess-spawn session\n  parlay subprocess-ping <id>     Exit 0 if a subprocess-spawn session is alive, 1 if not\n  parlay claim <task-id>          One-call agent bootstrap: profile + enroll + the task, from a ticket (idea-tm0)\n  parlay merge-gate <pr>          Is this PR ACTUALLY safe to merge? (catches green-but-vacuous checks)\n  parlay route decide <text...>   Deterministic-first routing: act (0), confirm (3), refuse (4), needs-inference (5)\n  parlay route why <text...>      Dry-run a routing decision: full evaluation trace, nothing recorded\n  parlay route propose --decision <id> --target <t> --confidence <c>   Record an inference result for a needs-inference decision\n  parlay route confirm <id>       Feedback: the routed/proposed target was right (--authority captain hardens)\n  parlay route correct <id> --target <t>   Feedback: it belonged at <t> — demotes the wrong route, teaches the right one\n  parlay route rule add|retire    Authored key→target rules; retire tombstones a rule or learned entry\n  parlay route explain <id>       Why did THAT decision route the way it did? Rule or inference, trace, feedback\n  parlay route rules              Every authored rule + learned entry: confidence, provenance, retired history\n  parlay landed <pr>              Did the fix ACTUALLY land? MERGED in THIS repo + commit on the remote base\n  parlay branch-audit [<branch>]  What does this branch REALLY change? (merge-base truth; behind != reverted)\n  parlay commands [--all] [--watch] [--json]   What is parlay running right NOW (live-command registry)\n  parlay action-log [filters] [--json] [--off <kind>:<id>]   The COMMAND log: one row per evaluated string, filterable\n  parlay off <connection|action> <id> | off status   Turn a connection or an action OFF (and 'parlay on' to restore)\n  parlay variant launch <id>      Fork a live agent into an isolated git-worktree variant\n  parlay variant list [<id>]      List variants (optionally filtered to one primary)\n  parlay variant merge <id>       Merge variant's insights back into primary (idempotent)\n  parlay variant teardown <id>    Merge + remove worktree + unregister variant\n  parlay crew-state <id>          Read an agent's current state (reconcile status vs oracle)\n  parlay explain <agent-id>       One agent's whole story: registration, channel, status, relay, queue, commands, last error\n  parlay timeline [<id>] [--since T] [--until T] [--outcome O]   What HAPPENED, on one axis: messages, lifecycle, delivery outcomes, commands\n  parlay liveness [<id>] [--silent] [--silent-for T]   Fleet liveness: which agents are silent, since when, absent vs expired heartbeat\n  parlay supervise <id>           Wake-on-actionable-status loop with absorb-when-working logic\n  parlay status-migrate --agents-root <dir> [--apply]   Replay legacy status files into the bead/event pipeline (dry-run default)\n  parlay teardown <id> [--force]  Safe destroy of an agent with worktree (refuses unlanded work)\n  parlay sweep [--apply]          Fleet closure sweep: close every done agent, surface the rest\n  parlay sweep --agent <id>       Sweep one agent by id (skips the per-task-spawn proof)\n  parlay stale <agent-id>         Is this pane worth sending to? FRESH (0) or STALE — relaunch (exit 3)\n  parlay guard [--repo P]         Runtime worktree-tangle + watcher-liveness alarm (advisory; never blocks)\n  parlay guard --beat             Touch the liveness beacon (watcher heartbeat, per poll cycle)\n  parlay lavish-import            Import lavish sessions\n  parlay city-scaffold [--json]   Materialise parlay's Gas City city under $PARLAY_STATE_HOME (inert files; starts nothing)\n  parlay gc-spawn <id> [flags]    Launch one agent as a Gas City session (opt-in gc launcher; see --help)\n  parlay gc-nudge <id> --session <sid> <msg...>   Capability-gated steering for a gc session (refuses no-injection providers)\n  parlay gc-liveness <id> --session <sid> --server <url>   Confirm-or-report startup watchdog for a gc session\n  parlay gc-resolve <id> [--json]   Resolve an agent id to its gc session via the bead-backed directory\n  parlay gc-teardown <id> [--json]   Close a gc session and reap its subprocess if `gc session close` left it running (#203)\n  parlay help                     Show this help\n\nAny subcommand accepts --help. Exit codes: 0 ok, 1 server/runtime error, 2 usage error.\n\nEnv:\n  PARLAY_SERVER   Server base URL override (highest precedence; wins over persisted config and the coded default)\n\nServer URL resolution (highest wins): PARLAY_SERVER env var > ~/.parlay/config.json (\"server\" key,\n  set via 'parlay remote set <url>') > coded default http://localhost:4242. See 'parlay remote --help'.\n"

// Usage renders the full USAGE text with the given server URL substituted in.
func Usage(server string) string {
	return strings.Replace(usageTemplate, "{{SERVER}}", server, 1)
}

// HELP is the per-command help text map, keyed by subcommand name.
var HELP = map[string]string{
	"spawn":          "parlay spawn — launch a new agent (the spawn pipeline runs in-process; task-42qot).\nUsage: parlay spawn <agent-id> <display-name> <hex-color> <initial-prompt> [--cwd PATH] [--focus]\n       parlay spawn --ephemeral <initial-prompt> [--cwd PATH] [--model MODEL] [--focus]\n       parlay spawn <id>=<repo> [<id>=<repo> ...] --prompt TEXT [--model M] [--color HEX] [--focus]\n       parlay spawn --list\nKey flags: --claim TASKID (ticket instead of inline prompt), --model MODEL (required unless --profile\nnames one), --profile NAME, --kind KIND, --pii/--no-pii, --mode report|branch|pr, --subprocess\n(herdr-free detached launcher), --pane PANE (spawn into an existing pane in place).\nRun with wrong/missing args for the full flag reference.",
	"reset":          "parlay reset — clean self-restart for a persistent agent (alias: reincarnate).\nUsage: parlay reset --reboot                    reboot a parlay panel agent (relaunch auto-derived from PARLAY_* env)\n       parlay reset --reboot --cmd '<launch>'   reboot with an explicit relaunch command (firstmate / custom hosts)\n       parlay reset                             no reboot — verify shutdown only (deliberate end)\n       parlay reset --dry                       print the plan; spawn nothing, kill nothing\nHARD RULE: never call this before a handoff bead exists and is pinned, or the rebooted you wakes\nwith amnesia. Prefer 'identity --submit', which pins the handoff and runs this atomically.",
	"status":         "parlay status — the fold's agent→supervisor keyed status verb (§3.6). Ports firstmate's grammar '<verb> [key=<slug>]: <note>'.\nUsage: parlay status <verb> [--key <slug>] <note...>   append a keyed status line\n       parlay status                                   read THIS agent's status file\n  Verbs: working, needs-decision, blocked, paused, done, failed, resolved.\n  Sink: $PARLAY_STATUS_FILE when set (firstmate injects it at spawn; its fm-watch loop reads it),\n        else ~/.parlay/agents/<id>/status keyed by PARLAY_AGENT_ID. Same verb, two homes.\n  --key <slug>  open/close a durable keyed decision (slug chars [A-Za-z0-9._-]); a bare needs-decision\n                uses key 'default', and 'resolved [--key <slug>]' closes the matching open decision.\n  Env: PARLAY_CREW_STORE=<beadsDir> — ALSO land every write in the crew bead store and the per-agent\n       events.jsonl (status-lift unit 3, dual-write shakedown). Unset = file-only, legacy-identical.\nNOTE: 'status' was formerly a redundant alias of bare 'parlay'. The panel/fleet snapshot now lives ONLY\n      on bare 'parlay'; this name was repurposed for the fold verb (task-ve2v resolves the C1 collision).",
	"subscribers":    "parlay subscribers — connection counts (panel clients, pollers, registered agents).\nUsage: parlay subscribers [--full]\n  --full   Print the raw JSON from /api/chat/subscribers",
	"agents":         "parlay agents — registered agents, one per line (id, name, color).\nUsage: parlay agents [--full]\n  --full   Print the raw JSON from /api/chat/agents",
	"agent-down":     "parlay agent-down — deregister any agent channel from the registry.\nUsage: parlay agent-down <id>\nGeneral-purpose counterpart to 'variant teardown' (which only unregisters git-worktree variants):\nany spawner (e.g. a firstmate crewmate) can call this on clean shutdown to remove its channel.\nPOSTs to /api/chat/unregister. Fails LOUD (non-zero exit, server's error message) on an unknown\nor already-gone id — never a silent success. On success prints a short confirmation.",
	"shutdown":       "parlay shutdown — explicit, idempotent graceful retirement of an enrolled agent (task-35ww).\nUsage: parlay shutdown <id>\nDoes the full teardown an agent (or its supervisor) should do on the way out, in one call:\n  1. Ends any local 'parlay listen'/'monitor' process for <id> on THIS host (SIGTERM, 2s grace,\n     then SIGKILL a survivor — same sequence 'parlay listen's singleton guard uses).\n  2. Deregisters <id> server-side (POST /api/chat/unregister), which tombstones the channel and\n     immediately resolves any in-flight long-poll on it rather than leaving it to time out.\n  3. The relay's own poll loop reacts to that (same 410/tombstone path a server-initiated prune\n     already uses — task-0n80i) and retires its local spool. No separate relay call is needed.\nIdempotent: a 404 from step 2 means <id> was already retired — that is this verb's SUCCESS case,\nprinted as 'already retired', not an error, so re-running it or racing a concurrent shutdown is safe.\nUnlike 'parlay agent-down' (fails loud on an unknown id), 'shutdown' is meant to be the one thing a\ndeparting agent (or a supervisor sweeping a dead one) can always call without checking state first.\nUndelivered messages queued for the channel are REPORTED (a count), never flushed or deleted — there\nis no other listener to hand them to, and discarding chat history is a separate, unrequested action.",
	"remote":         "parlay remote — persist a default server URL so a non-default server/relay target (e.g. a\nTailscale-networked host like 'mini1' talking to a relay on 'macbook:4242') survives across shells\nwithout re-exporting PARLAY_SERVER every session.\nUsage: parlay remote                  → print the current server URL + its source (env/config/default)\n       parlay remote set <url>       → persist <url> to ~/.parlay/config.json (\"server\" key)\n       parlay remote clear           → remove the persisted value (falls back to env/default)\nResolution precedence (highest wins): PARLAY_SERVER env var > persisted config > coded default\nhttp://localhost:4242. The env var always overrides — 'remote set' only changes the fallback used\nwhen PARLAY_SERVER is unset. State dir honors $PARLAY_STATE_HOME (default ~/.parlay), same as guard\nand robots-watch. Check which source is active with 'parlay doctor' or 'parlay remote'.",
	"defaults":       "parlay defaults — show or persist the default ccjuggler spawn account: the OAuth account agents come up under (all of parlay spawn, parlay launch, and listen --account resolve it).\nUsage: parlay defaults                     → show the current server URL + resolved spawn account\n       parlay defaults set account <n>     → persist <n> as the default (writes 'spawnAccount' in ~/.parlay/config.toml)\n       parlay defaults clear account       → remove the persisted value\nResolution (highest wins): PARLAY_SPAWN_DEFAULT_ACCOUNT env var >\n`spawnAccount` in ~/.parlay/config.toml > none. An env var set-but-empty falls through to the file.\nSetting it here replaces the old hand-edit: 'parlay listen --account <n>' (which calls this writer\nbefore enrolling) and 'parlay launch <id>' both honor the persisted default automatically. The server\nURL half is managed by 'parlay remote' and shown here read-only. State dir honors $PARLAY_STATE_HOME\n(default ~/.parlay), same as remote and guard.",
	"spawn-account":  "parlay spawn-account — the config-FILE-ONLY view of the default spawn account.\nUsage: parlay spawn-account                    show the persisted account (never the env var)\n       parlay spawn-account set <account>      persist it in $PARLAY_STATE_HOME/config.toml\n       parlay spawn-account clear              remove the persisted value\nPREFER 'parlay defaults': this verb reads the FILE only — it deliberately ignores\nPARLAY_SPAWN_DEFAULT_ACCOUNT, so a value set only in the environment reads as '(none)' here while\n'defaults' shows the one the spawn pipeline actually resolves. Both write the same config.toml key.\nRetained because the retired TS CLI shipped this name (robots-ni5p closed the dispatch gap by adding\nit back); 'parlay defaults' is the Go-native verb with the env-aware show.",
	"drawdown":       "parlay drawdown [N] — draft a HANDOFF prompt from the last N chat messages.\nUsage: parlay drawdown [N]        N defaults to 20; must be a positive number\nPrints a ready-to-paste markdown handoff: a UTC timestamp, a one-line summary (the newest agent-role\nmessage, clipped to 300 UTF-16 units), the last N messages in a fenced block, and a 'Next steps'\nscaffold to fill in. It ends with the two commands that submit it, where a `handoff` store exists:\n  handoff create \"<id> context handoff <ts>\" --description \"<paste body>\"\n  identity --submit\n`handoff` is a beads-store wrapper from the author's federation, NOT something this repo installs, so on a\nplain clone drawdown names the portable substitute instead (keep the body; pin any id with\n'identity --submit <handoff-id>'). It prints and submits NOTHING by itself — read it, edit 'Next steps', then\nrun those. Server-side\nhistory only (GET /api/chat/history?limit=N). Pairs with 'parlay idle' for a pause without a handoff.",
	"idle":           "parlay idle [hours] — signal that THIS agent is going quiet for a while.\nUsage: parlay idle [hours]        hours defaults to 1; must be a positive number\nAppends a 'paused' keyed status line carrying an estimated resume time (now + hours, UTC) to the SAME\nstatus sink 'parlay status' writes — $PARLAY_STATUS_FILE when the host injected one, else\n$PARLAY_STATE_HOME/agents/<id>/status — then prints where it wrote, who is going quiet, and the two\nways back: 'parlay status working \"resuming\"' to come back, or 'parlay drawdown' + 'identity --park'\nto park with a handoff instead. Nothing is killed and no bead is opened: unlike 'identity --park' this\nleaves the session running. It exists so a supervisor watching the status file can tell 'deliberately\npaused for 2h' from 'went silent'.",
	"nickname":       "parlay nickname — assign voice nicknames so the channel picker + voice channel-switch resolve an agent by an easy spoken word.\nUsage: parlay nickname <nick> [<nick2> …]        set nicknames for THIS agent (PARLAY_AGENT_ID)\n       parlay nickname --agent <id> <nick> …     set nicknames for a named agent\n       parlay nickname --agent <id> --clear      remove all nicknames\nThe FIRST nickname becomes the picker's display label for that channel. Metadata-only\nupsert via /api/chat/register-agent — does not post a message. Re-running replaces the set.",
	"send":           "parlay send — list or message another agent's channel (all messages visible to the human).\nUsage: parlay send                          → list agents you can message\n       parlay send --agent <id> \"text\"     → send attributed message to that agent's channel\n       parlay send --<agent-id> \"text\"     → same thing, shorthand form\nExamples:\n  send                          # prints: send --mayor, send --shepherd, …\n  send --agent mayor \"heads up\" # lands on mayor's channel; human sees it too\n  send --mayor \"heads up\"       # shorthand for the same send\n  send --shepherd \"done\"        # attributed to PARLAY_AGENT_ID (auto-filled)\n  --agent <id> | --to <id>      # explicit target (matches 'parlay listen --agent <id>')\n  --from <id>                   # override sender attribution (rarely needed)\n  --force                       # skip BOTH pre-flight checks below (seed a channel; wake a done pane)\nTwo pre-flight checks, both refusing with a non-zero exit and both failing OPEN:\n  1. REGISTERED? The target is checked against the live registry — an unregistered id is refused\n     rather than accepted onto a channel nothing polls (robots-ngg5: a send that returns a message\n     id but is never delivered gives the caller no signal to retry). An unreadable registry warns\n     on stderr and proceeds.\n  2. WORTH SENDING TO? A target that finished its task and is sitting at its prompt is a STALE\n     WINDOW — continuing it makes the new work re-pay for the whole finished session on every turn\n     (robots-9d2w). Refused with the relaunch commands; see 'parlay stale --help' for the policy.\n     Unknown state is never stale, so a relay hiccup can't become a refused send. --force waives it,\n     which is the right call for a follow-up question ABOUT the work the agent just finished.\nAll messages land on the target's SHARED human channel — no private side channels.\nThe receiving agent's monitor emits: CHAT_MSG|id|role|text|from:<sender>",
	"say":            "parlay say — reply to your OWN Parlay channel with no boilerplate (for agents spawned by 'parlay spawn').\nUsage: parlay say <text...>   |   echo \"long reply\" | parlay say\n  Identity comes from PARLAY_AGENT_ID (set at spawn); override with --agent <id>.\n  The server keeps your registered name/color, so you only supply the text.\n  Alias: parlay reply. Dead-simple wrapper on PATH: reply \"<text>\".\n  Shutdown guard: if you post while an OPEN handoff is not yet submitted, a loud stderr\n  warning steers you to 'identity --submit' — chat here is the create→submit death window.\n  The send still goes through; the warning never blocks it.",
	"scratchpad":     "parlay scratchpad — your durable task notes, keyed by PARLAY_AGENT_ID (survives restarts).\nUsage: scratchpad '<note>'   append   |   scratchpad   read   |   scratchpad --clear | --path\n  Also: --agent <id>, and stdin (echo 'note' | scratchpad). Store: ~/.parlay/agents/<id>/scratchpad.md",
	"identity":       "parlay identity — your durable self-knowledge (traits, failure modes, lessons), keyed by PARLAY_AGENT_ID.\nUsage: identity '<fact>'   add   |   identity   read   |   identity --clear | --path\n  identity --handoff [<handoff-id>]         pin a pointer to your handoff bead (pin only — does not restart).\n  identity --dismiss-handoff [<handoff-id>] NON-DESTRUCTIVE dismiss of an inherited stale handoff. Pins the pointer\n                                             (same as --handoff) but prints a \"dismissed, context NOT reset\" message.\n                                             Use when a fresh context reusing an agent-id sees a prior session's stale\n                                             open handoff and gets nagged. Does NOT trigger a context reset.\n  identity --submit [<handoff-id>]          PERSISTENT agent: pin it AND reset your context — ENDS the session and relaunches you with a\n                                     fresh context that recovers via identity -> handoff -> scratchpad. Add --dry to preview.\n  The handoff id is OPTIONAL where the store exists: omit it and your NEWEST OPEN handoff is resolved from the store\n                                     (agent-scoped), so creating the bead and submitting it is ONE atomic act — no room for an\n                                     interposed step to strand your shutdown, and a bare submit recovers a create that\n                                     already landed. With no store installed there is nothing to resolve, so the id must be\n                                     passed explicitly — see SCOPE.\n  ATOMIC CONTRACT: create then submit with NOTHING between. Post no chat in that window — 'parlay say'/'reply' will\n                                     warn you if you do. The pin is set at CREATE time, so recovery survives a missed submit.\n  identity --park [<handoff-id>]            PAUSE: pin the handoff AND shut down WITHOUT restarting — the session ENDS and does\n                                     NOT relaunch. The bound bead is left OPEN, which is the signal that work remains; a\n                                     future spawn (manual or mechanic-dispatch) resumes it, recovering via identity ->\n                                     handoff -> scratchpad. Same optional-id + atomic contract as --submit. Add --dry to preview.\n  identity --complete <store-item>  SINGLE-USE agent: close the work item you finished (e.g. task-abc → 'task close') and\n                                     END for good — no restart. The counterpart to --submit. Add --dry to preview.\n  Three-exit model: bead OPEN + continue now → --submit (restart); bead OPEN + pause → --park (stop, resume later);\n                                     bead CLOSED + done → --complete (terminate). All three are the whole shutdown — no separate\n                                     sudoku/context-reset step.\n  identity --rename <old-id> --to <new-id> [--name N] [--color C] [--cwd P] [--model M] [--preserve]\n                                     Move an agent's store to a new id and re-register with the server. Guards against\n                                     clobbering an existing <new-id>. --preserve drops the ephemeral marker (adopt an\n                                     ephemeral into a durable identity). Does NOT relaunch — relaunch with 'identity --launch <new-id>'.\n  identity --reap-ephemeral [--older-than <hours>h] [--dry]\n                                     GC ephemeral (hash-identity) agents whose identity.md is idle past the window\n                                     (default 24h). --dry previews without deleting.\n  Also: --agent <id>, and stdin. Read identity on every startup to recover yourself. Store: ~/.parlay/agents/<id>/identity.md\n  SCOPE: plain reads/appends and --register work standalone — nothing else is needed. The --handoff/\n  --submit/--park/--complete family resolves its id from a `handoff` store, which is a beads-store wrapper\n  from the author's federation (like task/inbox), NOT something this repo installs. Without it, pass an id\n  explicitly (identity --submit <handoff-id>) or skip that leg; scratchpad + identity are the portable pair.",
	"alert":          "parlay alert — broadcast an alert to pollers + agents.\nUsage: parlay alert [--agent <id>] <text...>\n  --agent <id>   Deliver only to one agent channel",
	"history":        "parlay history — print recent messages (server-bounded).\nUsage: parlay history [N] [--full]\n  N        How many messages (default 20)\n  --full   Untruncated text plus id and channel per message",
	"monitor":        "parlay monitor — enroll with the relay and stream CHAT_MSG|id|role|text lines on stdout.\nUsage: parlay monitor --agent <id> [--notify-safe] [--legacy-poll]\n  --agent <id>    Agent channel to enroll + stream (required unless --legacy-poll)\n  --notify-safe   Cap each emitted line to a notification-safe budget (PARLAY_NOTIFY_BUDGET,\n                  default 400) and append a \"fetch full text\" pointer. Use this when running\n                  under a harness Monitor tool: harness notifications truncate long lines\n                  mid-word silently, so a long voice-dictated message reaches the agent cut off\n                  with no signal. --notify-safe makes the cut deterministic, self-describing, and\n                  recoverable (the message id survives; 'parlay history --full' fetches the rest).\n                  Default off so raw programmatic consumers still get complete, unmodified lines.\n  --legacy-poll   Use the old independent poll loop with no relay (global feed if no --agent)\n  --reap          Maintenance sweep: list every channel reader under the relay runtime dir whose\n                  launcher chain is gone (dry run). Needs no --agent and no running relay.\n  --apply         With --reap, actually kill them (TERM, then KILL). Without it, nothing is killed.\n\nDefault path registers <id> with the central relay (tools/relay/parlay-relay must\nbe running) and streams the agent's spool with 'tail -F' — ~1.2MB per agent, one\nrelay fans out to all. See tools/RELAY_MONITOR.md.\n\nThe reader's lifetime is tied to this process (robots-3pvi): the monitor runs in its\nown process group, a signal here tears down the whole group, and if this process is\norphaned the reader is stopped rather than left tailing a channel forever. Enrolling\nalso evicts any other reader of the same agent id — an append-only spool with N\nreaders delivers every directive N times.\nSCOPE — that eviction is HOST-WIDE, not per instance: it matches the agent id in this\nhost's process table and discriminates neither server, state dir nor relay runtime dir.\nTwo parlay instances on one host (parlay-dev, a -state-dir server, 'parlay remote set')\ntherefore evict EACH OTHER's listener for a colliding id, even across different servers,\nleaving the loser registered but deaf. Give instances distinct agent ids, or set\nPARLAY_LISTEN_NO_SINGLETON=1 in the one that must not reap.\nOnly a process whose OWN argv[0] is 'parlay' or 'parlay-cli' is ever a candidate, so a script,\nshell, 'tmux send-keys' or agent harness that merely CONTAINS this command line is never\nreaped \u2014 arming from a wrapper cannot take the wrapper down with it. (The flip side is the\ncoverage hole: a renamed copy of the binary is not detected either, so duplicate delivery\nreturns silently.)\nRELAY SCOPE — the relay is one process per USER on the host-wide $TMPDIR/parlay runtime dir and\nbinds ONE -server for its whole life, so two instances on one host SHARE it. The pre-enrollment\npreflight compares the server the relay reports against the one this CLI resolved (PARLAY_SERVER)\nand exits 1 naming both on a mismatch, instead of enrolling into a relay that polls the other\ninstance: the enroll would succeed, the tab would look live, and nothing sent to your own server\nwould ever arrive. Three\nways out: --legacy-poll; a private relay (PARLAY_RELAY_RUNTIME=<dir> plus one started with -server\n$PARLAY_SERVER); or point PARLAY_SERVER at the server the existing relay already polls.\nSet PARLAY_MONITOR_NO_ORPHAN_EXIT=1 to deliberately outlive the launcher.",
	"listen":         "parlay listen — one-call agent self-enrollment (alias: agent-up). Atomically:\n  1. Registers <id> in the server's agent registry (POST /api/chat/register-agent) — identity + optional --caps.\n  2. Announces \"listening\" on the agent's own channel (POST /api/chat/reply).\n  3. execs into the SAME poll loop as 'parlay monitor --agent <id>' — reused, not duplicated.\nUsage: parlay listen --agent <id> [--name <name>] [--color <hex>] [--caps <json>] [--account <n>] [--notify-safe] [--legacy-poll]\n  --agent <id>    Required. Kebab-slug agent id.\n  --name <name>   Display name (default: <id>).\n  --color <hex>   Tab accent color (default: deterministic from <id>, same as ephemeral identities).\n  --caps <json>   Optional capabilities payload forwarded on registration.\n  --account <n>   Persist <n> as the default ccjuggler spawn account in ~/.parlay/config.toml BEFORE\n                  enrolling, so every subsequent spawn ('parlay spawn', 'parlay launch') comes up under\n                  it — see 'parlay defaults'. Written before any network call; idempotent; --account\n                  omitted never writes.\n  --notify-safe   Forwarded to the underlying monitor: cap each emitted line to a notification-safe\n                  budget (PARLAY_NOTIFY_BUDGET, default 400) so a long captain message can't blow the\n                  agent's context on delivery under a harness Monitor. See 'parlay monitor --help'.\n  --legacy-poll   Forwarded to the underlying monitor (no relay).\nArming is a TAKEOVER (robots-fgyz): before step 1, any OTHER live poll loop for this agent id\nis ended (SIGTERM, then SIGKILL for a survivor), announced on stderr, so one id keeps exactly\none reader. Without it every restart/reconnect/turn added a loop and each message was processed\nonce per loop — the Mayor agent reached 12. Safe to re-run on every restart (e.g. from a\nSessionStart hook), so a single\n'Monitor({ command: \"parlay listen --agent <id>\", persistent: true })' call is the whole enrollment.\nSCOPE — the takeover is HOST-WIDE, not per instance: the match is the agent id in this host's\nprocess table, with no server, state-dir or relay-runtime-dir discrimination. Run two parlay\ninstances on one host (parlay-dev, a -state-dir server, 'parlay remote set') and 'parlay\nlisten --agent X' in the second one SIGTERMs the first one's listener for X — across different\nservers — leaving that instance registered but deaf. Give instances distinct agent ids, or set\nPARLAY_LISTEN_NO_SINGLETON=1 to skip the reap in the one that must not evict (duplicate delivery\nbecomes possible; the skip is announced on stderr).\nOnly a process whose OWN argv[0] is 'parlay' or 'parlay-cli' is ever a candidate, so a script,\nshell or agent harness that merely CONTAINS this command line is never reaped \u2014 arming from a\nwrapper cannot kill the wrapper (it used to; fixed 2026-10-05). The flip side: a renamed copy\nof the binary is not detected either, so duplicate delivery returns silently.\nWithout --legacy-poll this enrolls through the RELAY, which is one process per user on a\nhost-wide $TMPDIR/parlay runtime dir bound to ONE -server for life — a second instance on this\nhost shares it. The preflight compares the server the relay reports with the one this CLI\nresolved (PARLAY_SERVER) and exits 1 naming both on a mismatch, rather than enrolling into a\nrelay that polls the other instance (registered, live-looking, permanently deaf). Use\n--legacy-poll, a private relay (PARLAY_RELAY_RUNTIME=<dir> + one started with -server\n$PARLAY_SERVER), or point PARLAY_SERVER at the relay's server.",
	"stats":          "parlay stats — message memory and complexity snapshot from the server.\nFetches up to 2000 messages and reports: count, total estimated size, avg/largest message, user vs agent split, image attachments, action cards, oldest/newest timestamps.\nPair with Ctrl+Shift+D in the panel for bundle load timing and live memory breakdown.",
	"health":         "parlay health — the SERVER's vitals in one glance.\nChecks, and only these:\n  1. SERVER reachable — one probe of /api/chat/subscribers yields the panel-client, poller and\n     registered-agent counts plus memory and history stats. The first line is labelled 'server',\n     never 'relay': parlay ships a SEPARATE relay daemon (tools/relay, the per-agent spool fan-out\n     that 'parlay monitor' needs unless you pass --legacy-poll) and this check does not touch it.\n  2. eval-engine /health — protocol version of the optional voice engine. The engine has no state\n     dir and no persisted config: its identity IS its address, so the default 127.0.0.1:4343 is a\n     HOST-WIDE slot, and PARLAY_EVAL_ENGINE_URL is the only way to point this check elsewhere. If\n     you are running a second parlay instance (parlay-dev, -state-dir, 'parlay remote set') and\n     leave the default in place, a green engine line is annotated as the host's, not this\n     instance's.\nExit 1 if either is down. The eval-engine is OPTIONAL for the substrate this repo ships working:\nthe CLI, the HTTP API and the panel's text chat need no other service, so on a fresh clone a dead\nengine is a FAIL of the ENGINE, not of your install — start one only if you want spoken or typed\nphrase commands ('parlay eval serve').\nEnv: PARLAY_SERVER, PARLAY_EVAL_ENGINE_URL.\nSame view for every caller — for YOUR OWN state, run: parlay doctor",
	"doctor":         "parlay doctor [--json] — THIS agent's self-diagnosis; every check prints PASS/WARN/FAIL plus the fix command.\nChecks: server URL source (env/config/default) → PARLAY_AGENT_ID set → server reachable → registered\nwith the server → monitor listening (presence) → identity.md/scratchpad.md exist, identity frontmatter parses\nand matches the agent id (handoff pointer noted) → eval-engine reachable → Gas City gc prerequisite\n(named WARN with install pointer when missing/too-old/broken; FAIL when PARLAY_SPAWN_LAUNCHER=gc —\nsee docs/gc-prerequisite.md; PARLAY_GC overrides the PATH lookup). Runs every check even after\nfailures. Exit 1 if anything FAILed.\n--json: same checks, one JSON document on stdout (schema \"parlay.doctor/v1\") — top-level verdict +\nsummary counts + per-check {id, verdict, summary, evidence, fixes: [{argv, reversible, idempotent,\nhealable}]}. Same exit-code contract as text mode. For scripts/LLM callers, not humans.\nSubcommand: parlay doctor deploy [--json] — the deployment-level sweep (NOT run by plain\ndoctor); read-only probes of launchd service inventory + binary-path sanity, /health\nretry-and-deadline (against the SAME endpoints the rest of the CLI resolves —\nPARLAY_SERVER / `parlay remote set` config / PARLAY_SERVER_ADDR, and\nPARLAY_EVAL_ENGINE_URL / PARLAY_EVAL_ADDR; --json records which), advisory log freshness,\nand pin-vs-doc consistency. Exit 1 iff any FAIL. --json emits the same parlay.doctor/v1 schema.\nEnv: PARLAY_SERVER, PARLAY_AGENT_ID, PARLAY_AGENT_HOME, PARLAY_EVAL_ENGINE_URL, PARLAY_STATE_HOME,\nPARLAY_GC, PARLAY_SPAWN_LAUNCHER, PARLAY_SERVER_ADDR, PARLAY_EVAL_ADDR.\nSee 'parlay remote --help' for the persisted server-URL config.",
	"heal":           "parlay heal — Doctor v2 stage 3: the guarded self-heal verb (design #256 §3).\nUsage: parlay heal <check-id>   — apply the whitelisted fix for ONE failing check, then re-verify\n       parlay heal --all        — converge every FAIL/WARN check across the doctor + deploy registries\nA STRICT WHITELIST of mechanical fixes, one per check, is the WHOLE budget — everything else refuses:\n  agent-registered / monitor-listening   re-enroll by arming the agent's monitor poll loop\n  deploy-launchd                        bootstrap an installed-but-not-loaded com.parlay service\n  deploy-service-health                 restart a down service under launchd (kickstart the loaded\n                                        job owning its port; bootstrap if installed but not loaded)\n  deploy-registry-reconcile             deregister stale registered records (ghost agents)\nEvery fix re-verifies: the same check re-runs after the fix, and a still-failing check is retried up to\n3 times before being reported. Checks NOT on the whitelist — rebuilds, operator choices, prose fixes —\nare REFUSED with exit 1 and zero mutation. `parlay doctor --json` marks the same whitelist via each\nfix's healable flag, so the diagnostician and the healer can never disagree.\nExit codes: 0 all targeted healed (or already fine); 1 a fix was refused or still failing after\nre-verify; 2 usage. Scratch-instance caveat: heal runs the whitelisted action against the CURRENT\nserver (PARLAY_SERVER / persisted remote) and launchd domain this shell sees — point PARLAY_SERVER at\na scratch deployment and PARLAY_STATE_HOME away from ~/.parlay before healing real services.",
	"gc-spawn":       "parlay gc-spawn — launch one parlay agent as a Gas City session (spawn-lift unit 5).\nUsage: parlay gc-spawn <id> [--name <n>] [--color <#hex>] [--prompt-file <f>] [--cwd <dir>] [--model <m>]\n                        [--kind claude|pi] [--account <a>] [--server <url>] [--start-command <cmd> [-- <args...>]] [--json]\nThe Go half of the PARLAY_SPAWN_LAUNCHER=gc launcher (strictly opt-in; herdr stays the default):\nresolves the pinned gc ($PARLAY_GC wins, else PATH; refuses loudly if absent), reconciles the city\nscaffold, bootstraps the city bead store with the brain bd (idempotent — see docs/agent-notes/gc-main-brain-probe.md), synthesises the agent\ntemplate from the spec, then runs\n  gc --city <scaffold> session new parlay.<id> --json --no-attach\nwith a parlay-owned GC_HOME (supervisor port redirected off the shared :8372 singleton) and the\nClaude Code nesting markers scrubbed from the child env. The city runs the herdr session\nprovider, so the session starts as a tab in the city's shared herdr session-server.\n  --kind           agent harness to start: claude (default) or pi (its own --model flag, never\n                   claude's YOLO set); anything else refuses loudly — use herdr or --subprocess\n  --prompt-file    file whose contents become the agent's startup prompt (never argv — may be long)\n  --start-command  verification escape hatch: start <cmd> instead of the kind's harness (positionals\n                   after the id become its args); prompt_mode is then none\n  --json           machine-readable: {ok, agent_id, session_id, session_name, template, city_dir, gc}\nSECURITY: template env is persisted to disk — never pass secrets (OAuth tokens) through this verb.\nEnv: PARLAY_GC (gc binary override), PARLAY_BD (bd override; else first bd on PATH — the brain binary),\nPARLAY_STATE_HOME (scaffold + GC_HOME root).",
	"gc-nudge":       "parlay gc-nudge — capability-gated steering for a gc-launched session (spawn-lift unit 6, R7).\nUsage: parlay gc-nudge <agent-id> --session <gc-session-id> <message...> [--json]\nThe ONE seam through which parlay steers a gc session. Reads the city scaffold's [session] provider\nand refuses — typed JSON, gc never invoked — when that provider declares no interactive injection\ncapability at the pin. The subprocess provider's Nudge is a SILENT NIL NO-OP (gc's own `session\nnudge` would report it delivered), so refusing honestly here is the only non-lying behavior.\nInjection-capable providers (tmux) delegate to `gc session nudge --json` and pass through its\ntyped confirm result. Unknown providers refuse (fail toward not steering).\n  --json  {ok, agent_id, session_id, provider, refused, reason, gc_result}\nExit codes: 0 delivered-and-confirmed; 1 refused/unconfirmed/error (parse the JSON to distinguish).\nEnv: PARLAY_GC (gc binary override), PARLAY_STATE_HOME (scaffold root).",
	"spawn-watchdog": "parlay spawn-watchdog — post-launch liveness watch for one spawned agent (task-br4r6).\nUsage: parlay spawn-watchdog <agent-id> --launcher <herdr|subprocess|gc> --server <url> [--timeout-ms N]\n         [--agent-dir DIR] [--prompt-file PATH] [--session SID] [--city DIR]\n`parlay spawn` arms this as a DETACHED child after a successful launch — it is not normally run by\nhand. One arm per launcher: herdr waits for the agent to reach 'working' and re-sends the charter if\nthe first turn never fired; subprocess polls /api/chat/subscribers for the agent's own channel and\nreports (never re-prompts, since the charter went to stdin once); gc delegates confirm-or-report to\n'parlay gc-liveness' and appends its envelope to <agent-dir>/charter-delivery.\n  --timeout-ms  the 'did the first turn fire' window (default 60000)\nExit codes: 0 confirmed (or nudge delivered); 1 never observed; 2 usage error.\nEnv: PARLAY_SPAWN_NO_WATCHDOG=1 stops 'parlay spawn' arming it at all; PARLAY_SPAWN_LIVENESS_TIMEOUT_MS\ntunes the window. Logs land in $TMPDIR/parlay-watchdog-<launcher>.log.",
	"gc-liveness":    "parlay gc-liveness — confirm-or-report startup watchdog for a gc-launched session (spawn-lift unit 6).\nUsage: parlay gc-liveness <agent-id> --session <gc-session-id> --server <url> [--timeout-ms N] [--json]\nThe charter goes out exactly once, at session start, via the synthesised template. This verb then\nCONFIRMS the startup turn from the agent's own emitted effect — its channel appearing in the parlay\nserver's /api/chat/subscribers — or REPORTS that it never fired. It NEVER re-prompts the charter:\non timeout, steering routes through the gc-nudge capability gate, which refuses on the subprocess\nprovider (R7). Its --json envelope is the durable charter-delivery record 'parlay spawn-watchdog' appends\nto the agent dir.\n  --timeout-ms  poll bound for the confirmation window (default 60000; a bound, not an assertion)\n  --json        {ok, agent_id, session_id, confirmed, via, steer, error}\nExit codes: 0 confirmed (or capable-provider kick confirmed); 1 otherwise.\nEnv: PARLAY_GC (gc binary override), PARLAY_STATE_HOME (scaffold root).",
	"gc-resolve":     "parlay gc-resolve — resolve a parlay agent id to its Gas City session (spawn-lift unit 7).\nUsage: parlay gc-resolve <agent-id> [--json]\nIdentity is dual-written at spawn: identity.md carries the gc_session/gc_city pointer as a\nPROJECTION, but the source of truth is the city's bead store (gc's AddressDirectory doctrine —\nsession state is bead-backed, so an id stamped before a supervisor restart still resolves after\nit). Resolution mirrors the directory's order over `gc session list --state all --json`:\n  1. exact bead-id match on the stamped gc_session, closed sessions INCLUDED\n     (a retired session's identity still resolves);\n  2. else a live session whose template (or exact session_name) is parlay.<agent-id> —\n     the pin records `session new parlay.<id>`'s argument as the template and generates an\n     \"<id>-adhoc-<hash>\" session_name. Two live claimants = error, never a guess.\n  --json  {ok, agent_id, session_id, session_name, state, closed, via, city, stamped, reason}\nExit codes: 0 resolved; 1 not resolved (no match, ambiguity, or error).\nEnv: PARLAY_GC (gc binary override), PARLAY_STATE_HOME (scaffold root), PARLAY_AGENT_HOME (identity store).",
	"gc-teardown":    "parlay gc-teardown — the parlay-side reap seam for issue #203 (gc session close orphans its subprocess).\nUsage: parlay gc-teardown <agent-id> [--json]\n`gc session close` is supposed to stop a subprocess-provider session's child process, but at the pinned\ncommit it can silently fail to: the child reparents to pid 1 and keeps running. This verb never trusts\ngc's own success report either way — it resolves the session (gc-resolve's directory order), calls\n`gc session close`, then ALWAYS re-verifies from the process table afterward by scanning for live\nprocesses whose environment carries GC_SESSION_ID=<session-id> (internal/procscan — the same identity\nsignal Gas City's own orphan detection uses, chosen because it survives reparenting and is immune to\npid-reuse). Anything still matching is reaped: SIGTERM, re-verify, SIGKILL, re-verify.\nFail-closed: a process-table scan that cannot even run (unreadable /proc, missing ps) makes this verb\nREFUSE and report why rather than guess at a pid — a pid alone is never proof of ownership.\n  --json  {ok, agent_id, session_id, city_dir, resolve_via, closed, close_error, orphan_pids,\n           reaped_pids, survived_pids, refused, reason}\nExit codes: 0 no orphan (or none ever existed); 1 refused (indeterminate, nothing touched) or an\nincomplete reap (signaled, but a survivor remains) — the JSON's refused/reason fields say which.\nScope: this is the immediate, supervisor-independent half of design #252 — the health-patrol-tick\ncontinuous auto-reap is deferred follow-up work, not part of this verb.\nEnv: PARLAY_GC (gc binary override), PARLAY_STATE_HOME (scaffold root), PARLAY_AGENT_HOME (identity store).",
	"city-scaffold":  "parlay city-scaffold — materialise parlay's Gas City city under $PARLAY_STATE_HOME (spawn-lift unit 3).\nUsage: parlay city-scaffold [--json]\nReconciles <state-home>/gascity/city against the repo's authored city/ tree (embedded in the binary,\nsync-test-enforced byte-for-byte): managed files are created or overwritten-on-drift, the .gc/ state\ndirectory is created if absent, and NOTHING else is touched — .gc/ contents are gc's own machine-local\nstate and are never clobbered. Idempotent; each run reports created/updated/unchanged per file.\n  --json   machine-readable: {dir, files: {<rel-path>: created|updated|unchanged}}\nThe scaffold is INERT FILES: this verb never runs gc, never starts a city, and never talks to the Gas\nCity supervisor (a shared machine-wide singleton — see docs/gc-prerequisite.md for the safety rules).\nVerify read-only with a pinned gc build: <gc> --city <dir> session list --json (expect zero sessions).\nEnv: PARLAY_STATE_HOME (scaffold root; default ~/.parlay).",
	"launch":         "parlay launch — discover and launch agents defined in ~/.parlay/agents/.\nUsage: parlay launch          → list all known agents with live status\n       parlay launch <id>    → spawn the named agent via 'parlay spawn' (reads identity.md for name/color/cwd/model/account)\nOffline agents are clearly marked; spawning fires the standard identity→handoff→scratchpad recovery chain.\nThe agent respawns on its OWN ccjuggler account, never the launching shell's ambient token: the identity's\n`account:` frontmatter wins, else the configured default (PARLAY_SPAWN_DEFAULT_ACCOUNT, else `spawnAccount` in\n~/.parlay/config.toml). With none of those set, no --account is passed at all and the agent comes up on the ambient session token.\nLiveness is the REGISTRY intersected with the process table, never the registry alone (robots-jkwc):\n  [live]    registered AND a real 'parlay listen --agent <id>' process is running on this host\n  [ghost]   registered but NOTHING is listening — messages to it are accepted and silently lost.\n            Re-arm the agent, or clear the stale row with 'parlay agent-down <id>'.\n  [offline] not in the registry at all — 'parlay launch <id>' to spawn it.\nA registration is a row nothing removes when a listener dies, so registry-only status reported 148\nagents live against 11 real listeners. If the process table cannot be read, registered agents stay\n[live]: a failed probe is not evidence of a dead listener.",
	"claim":          "parlay claim — one-call agent bootstrap (idea-tm0): profile + enrollment + the task, from a ticket.\nUsage: parlay claim <task-id> [--agent <id>] [--name <name>] [--color <hex>] [--model <m>] [--no-register] [--allow-closed] [--silent]\nA freshly-launched agent runs this and follows its printed brief. In one call it:\n  1. Resolves its agent PROFILE (id/name/color/model): flags > env (PARLAY_AGENT_ID/_NAME/_COLOR/_MODEL) >\n     the ticket's own metadata (parlay_agent_id/parlay_name/parlay_color/parlay_model) > derived (color from id).\n  2. ENROLLS: registers with the chat server + announces the claim on its channel (tab goes live now), then\n     prints the ONE 'parlay listen' Monitor command to arm its persistent poll loop (a CLI can't arm a harness\n     Monitor itself). --no-register skips the synchronous register/announce (still prints the brief);\n     --silent prints no arm-command and no Monitor{} instructions at all, for scripted/headless/batch\n     claims with no harness to arm one in — it still registers and announces, and the brief says plainly\n     that nothing is listening on the channel.\n  3. Resolves the TASK: <task-id> against the beads/robots federation (task-/robots-/idea-…), printing the\n     ticket's title + description as the actual work — so the task prompt lives on the ticket, not the spawn prompt.\nTask-id resolution shells out to the store wrapper for the id's leading token (task/robots/idea/…), falling back\nto a bare 'bd' on PATH. Exit 2 if <task-id> or an agent id is missing.\nNO WORK behind the claim (the ticket doesn't resolve, or resolves already CLOSED) does none of the above:\n  it records 'failed' in the agent's status file, announces the failure on its channel, prints the exit\n  procedure (create a handoff, then 'identity --park' — the shutdown that does NOT relaunch), and exits 1 — so the\n  agent ends instead of lingering on an empty pane (robots-4ek1). --allow-closed claims a closed ticket anyway.",
	"route":          "parlay route — deterministic-first routing with confidence and progressive hardening (#128; model in docs/routing.md).\nEvery decision answers: which target should hear this input? Deterministic layers are consulted first\n(explicit address in the caller-supplied roster → authored rules → hardened learned entries); a model is\nnever called by this verb — when nothing deterministic decides, the decision is recorded as\nneeds-inference and whatever workflow owns the input runs inference and reports back via 'propose'.\nUsage: parlay route decide <text...> [--targets a,b,c] [--json]\n         Evaluate + RECORD a decision on the ledger. Prints the outcome, target, basis, confidence,\n         and the decision id. --targets supplies the known-target roster (agent ids / channel names);\n         without it only authored rules and learned evidence apply.\n       parlay route why <text...> [--targets a,b,c] [--json]\n         DRY RUN: the same evaluation with its full step-by-step trace, nothing recorded.\n       parlay route propose --decision <id> --target <t> --confidence <0..1> [--json]\n         Record an external inference result for a decision that came back needs-inference. The policy\n         classifies the confidence (act / confirm / refuse) and the proposal lands on the ledger.\n         Refused for decisions the deterministic layer already answered — inference is an escalation,\n         never an override.\n       parlay route confirm <id> [--authority captain|agent]\n         The routed/proposed target was right. CAPTAIN confirmations are the only evidence that\n         hardens: confidence is the Beta(1,1) posterior (confirms+1)/(confirms+corrections+2), so three\n         clean captain confirms reach the default 0.80 act threshold and the route starts acting\n         silently. Agent feedback is recorded for observability and NEVER counts (VISION.md — an agent\n         must not harden its own guesses). --authority defaults to agent: unlabeled feedback fails\n         toward not-hardening. Authority is declared, not authenticated (docs/routing.md gap-fill 3).\n       parlay route correct <id> --target <t> [--authority captain|agent]\n         It belonged at <t>. Demotes the decided (signal → wrong target) evidence — one captain\n         correction drops a 3-confirm hardened route below act, so it goes back to asking — AND\n         confirms (signal → <t>), teaching the right route in the same stroke. On a needs-inference\n         decision it is pure teaching. A hardened rule loses authority the same way it gained it:\n         arithmetic over captain feedback, no flag to flip.\n       parlay route rule add --key <k> --target <t> [--id <id>] [--note <n>]\n         Authored deterministic rule (key stored normalized; word-boundary prefix match; longest wins).\n       parlay route rule retire <rule-or-evidence-id> [--note <why>]\n         Tombstone an authored rule or learned entry: it never matches again, but its history and\n         provenance are preserved (#128 §79 — history is never destroyed).\n       parlay route explain <ledger-id> [--json]\n         Why did that recorded decision route the way it did — and was it a rule or an inference?\n         Replays the stored evaluation trace plus every follow-up (proposals, confirms, corrections)\n         that references it, straight off the append-only ledger.\n       parlay route rules [--json]\n         The whole table: active policy thresholds, every authored rule, every learned entry with its\n         confirm/correction counts, confidence, provenance, and retired tombstones.\nExit codes (decide/propose): 0 act (route it), 3 confirm required, 4 refused, 5 needs-inference,\n1 runtime error, 2 usage. Only 0 means \"go ahead\" — callers branching on non-zero fail closed.\nFeedback/rule verbs exit 0 on success, 1 runtime, 2 usage.\nAmbiguity never auto-acts: two qualifying targets at the same layer → confirm, both listed.\nState: $PARLAY_STATE_HOME/routing/ (policy.json thresholds, rules.json authored+learned entries,\ndecisions.jsonl append-only ledger). A corrupt policy/rules file fails LOUD; missing files mean\ndefaults (act ≥ 0.80, refuse < 0.50) and an empty ruleset.",
	"merge-gate":     "parlay merge-gate — the truthful \"is this PR actually safe to merge?\" check (robots-jap6).\nUsage: parlay merge-gate <pr> [--repo owner/name] [--json]\nA green status check is NOT evidence that anything reviewed the code. CodeRabbit reports a check\nCONCLUSION of 'pass' even when it never ran (account-wide review rate limit) — only the free-text\ndescription says so — and it reports success regardless of how many findings it posted. An agent\nfollowing 'merge when all required checks are green' therefore auto-merges unreviewed code.\nThis verb refuses to treat the check conclusion as the merge signal. It asserts, in order:\n  1. PR is OPEN and not CONFLICTING\n  2. at least one check exists; none failing, none pending\n  3. no VACUOUS pass — green conclusion whose description admits it did not run\n  4. a review actually happened — a human review, or a CodeRabbit comment carrying a real-review\n     marker rather than the rate-limit template\n  5. that review covered the CURRENT head sha, not an older push\n  6. no review thread left unresolved\n  7. the LOCAL copy of the head branch is not ahead of origin's — i.e. the fix you just pushed has\n     actually ARRIVED at origin, so the verdict is about the commit you mean (robots-bn5d)\nExit codes: 0 ready (or already merged), 3 BLOCKED on the code (fix it on the branch), 5 PENDING (the\nreview is still running — nothing is known to be wrong yet), 6 INFRA (every red is a check that failed\nWITHOUT evaluating the diff — re-run the jobs), 4 NEEDS-DECISION (every blocker is the reviewer being\nunavailable — nothing on the branch changes it), 1 gh/network could not answer, 2 usage.\nFail-closed in every direction — a caller branching on non-zero refuses correctly. Class precedence is\ncode > pending > infra > reviewer-unavailable, so one real finding always keeps the whole verdict at 3.\nOn 6 (robots-6mw2), do NOT hunt a defect: a GitHub Actions job that dies in action setup ('Failed to\nresolve action download info' / 'Service Unavailable') reports bucket=fail with an EMPTY description,\nidentical to a real failure by status alone. The check run's ANNOTATIONS are the discriminator — a job\nthat ran the code always annotates 'Process completed with exit code N'. Re-run the failed jobs\n('gh run rerun <run-id> --failed --repo owner/name'), then re-run the gate; if a re-run dies the same\nway, that is a GitHub incident — signal needs-decision rather than re-running forever.\nOn 5, do NOT edit the branch (there is no defect yet, and a new push restarts the review in flight) and\ndo not merge — just re-run the gate once the check reports (robots-rwf8). Bound that wait: a check that\nnever finishes is a 4.\nOn 4, do not poll, do not edit the branch, and do not merge anyway: 'parlay status needs-decision' and\nlet the captain pick re-request / merge-and-disclose / park (robots-8kkq). An unbounded wait on a\nrate-limited reviewer is itself a defect — and waiting cannot work here, since CodeRabbit only reviews\non a new push or an explicit '@coderabbitai review' comment, never when the window lapses (robots-eowy).\nA refusal counts wherever it is written down: CodeRabbit edits its one comment in place, so after a\nlater push the refusal often exists ONLY in the check description. A vacuous check therefore reclassifies\n'stale-review' and 'no-review-evidence' to reviewer-unavailable exactly as a rate-limit comment does —\nthat pairing (vacuous-pass + stale-review) used to exit 3 and send a mechanic editing unobjected-to code.\nHead freshness (robots-bn5d): every rule above is evaluated against ORIGIN's head, which is the commit\na merge lands — but a mechanic who has just pushed a fix reads READY as a verdict on THAT. If the push\nwent to the no-mistakes mirror and the pipeline has not reached origin yet, merging lands the OLD head\nand silently drops the fix. So origin's head sha is printed on every verdict, and when this checkout has\na local copy of the head branch that is AHEAD of origin's head the gate returns 5 with 'head-not-pushed'.\nOn that 5, do not merge and do not edit: get the commits to origin, then re-run (a new head restarts the\nreview, so a 0 can legitimately become 3/4/5 afterwards). Where no local branch is available to compare,\nthe gate says the freshness is UNVERIFIED rather than implying agreement.\nMerged is not always LIVE (robots-oex0): when the local base branch is ahead of origin's copy, the gate\nsays ORIGIN LAGS LIVE in the header and names the reconcile step. It is a note, never a blocker — the\nPR is still safe to merge; what is unsafe is concluding 'merged, therefore fixed'. Seen in pai-hooks,\nwhere ~/.claude/hooks symlinks into the checkout, so local main is live and origin ran 20 commits behind.\nWhich repository (robots-g4qz): --repo wins; otherwise the `origin` remote; only with no usable origin\ndoes it fall back to gh's own pick. gh prefers a remote named `upstream` over `origin`, so in a FORK\nclone its pick is the parent project — a silent, well-formed verdict about a different repository's PR\nof the same number (worst case exit 0 'already MERGED' for a still-open, unreviewed fork PR). Every run\nprints the repo it answered about, and warns when GitHub answers for a different one.\nRun it before any merge: parlay merge-gate 45 || echo REFUSING",
	"branch-audit":   "parlay branch-audit — what does this branch REALLY change? (robots-d988).\nUsage: parlay branch-audit [<branch>] [--base <ref>] [--repo <path>] [--json]\n`git diff origin/main <branch>` does not answer a question about the branch. Two-dot diff renders the\nSYMMETRIC difference between two tips, so every file that exists only on main comes back as a D\n(deleted) line and every line main gained since the branch was cut comes back as a `-`. A branch that\nis merely N commits behind therefore reads as having deleted work it never touched.\nObserved on ~/code/firstmate (robots-90i7): a 16-commits-behind branch reported 75 files / 2990\ndeletions and 4 files 'deleted' from two already-merged PRs. Its real contribution was 21 files, all\nadditions, 1214 insertions, ZERO deletions — and the false positive escalated to 'do NOT merge,\nconsider discarding the branch and redoing the work'.\nThis verb never diffs tip against tip. It reports, separately:\n  1. TRUE CONTRIBUTION — git diff <merge-base> <branch> (equivalently <base>...<branch>)\n  2. STALENESS — 'N commits behind' on its own line, as a fact, never as a deletion\n  3. MERGE STRIPS — for every merge in <base>..<branch>, a diff against its OWN parents; a file a\n     parent had ADDED that the merge dropped is a real strip, while a file that predates both sides is\n     a deliberate delete on one side and only a note\nExit codes: 0 nothing dropped merged work — INCLUDING a badly-behind branch, and including files the\nbranch's own commits delete (deleting a file is ordinary work); 3 STRIPPED, a merge dropped a file no\ncommit on the branch authored a delete for (fix it on the branch, usually by rebasing the real work off\nthe poisoned base); 1 git could not answer; 2 usage.\nOut of scope on purpose: line-level reverts inside a file a merge MODIFIED rather than deleted. That\nneeds semantic review, and claiming to catch it here would be the same overreach this verb removes.\nBefore ever reporting that a branch reverts merged work: parlay branch-audit <branch> || echo STRIPPED",
	"commands":       "parlay commands — what is parlay running right NOW.\nUsage: parlay commands [--all] [--watch] [--agent <id>] [--verb <verb>] [--json]\nReads the server's live-command registry: one record per invocation that reported itself, with its\nverb, agent, pid, age, and how it ended. The chat panel's live-commands view renders the SAME server\nstate, so the two surfaces cannot disagree.\n  --all      also show recently finished/failed/expired records, not just running ones\n  --watch    follow changes over the existing SSE stream (one connection, no polling)\n  --json     machine-readable; same field names the panel sees\n  --agent    only this agent's invocations       --verb   only this verb\nWHAT THIS CANNOT SEE (by design — a view that silently omitted half the fleet would be worse):\n  · only the Go CLI reports itself; shell wrappers (parlay-monitor.sh), the retired TS\n    CLI, and work the server originates on its own are NOT tracked\n  · `parlay commands` itself is excluded, so the observer never appears in its own output\n  · set PARLAY_COMMAND_REPORT=0 to opt an invocation out of reporting entirely\nWHAT IS NEVER RECORDED: flag VALUES, positional arguments, message bodies, paths, raw argv. Only the\nverb, the agent id, the pid, and flag NAMES travel — command lines routinely carry secrets.\nA command killed without reporting its end is reaped by the server after ~90s and shown as `expired`\n(outcome no-heartbeat), never left permanently `running`. See docs/live-commands.md.\nExit codes: 0 ok (including \"the server is too old to have a registry\" — reported, not fatal); 1\nserver/runtime error — the server is unreachable, or `--watch`'s event stream ended; 2 usage.",
	"action-log":     "parlay action-log — the COMMAND log: one row per evaluated string, and the off switch reachable from it.\nUsage: parlay action-log [filters] [--json] [--off <kind>:<id>]\n       parlay action-log status\nThis is the log the sandbox test page renders, in a terminal. It answers what the live-command\nregistry cannot: what did this string resolve TO, and did the result actually reach anyone?\nEach row is: time, source, outcome (and why), input action → output actions.\nFILTERS (any combination; every one is applied server-side, so a narrow view costs less):\n  --source test-site|panel|engine|remote-input      where the evaluation came from\n  --input-action <command-id>                      what it resolved TO (the engine's `fired` id)\n  --output-action <verb>                           a verb it would emit (setText, clear, submitNow, …)\n  --outcome delivered|queued|dropped|refused        how far the result actually got\n  --reason <token>                                 the why-behind-it (no-match, no-subscriber,\n                                                   engine-unreachable, off-connection, off-action,\n                                                   preview-suppressed, submit-armed)\n  --device <id>                                    one connection\n  --since/--until <RFC3339|15m|2h>                 a time window; a bare duration is measured\n                                                   back from now, and `-15m` means the same thing\n  --limit <n>                                      page size (server caps it)\n  --json                                           machine-readable; same field names the API sends\nTHE OUTCOME VOCABULARY is the point of the log. A filter that could not tell delivered from\nqueued from dropped from refused would be decoration:\n  delivered — reached at least one live client\n  queued    — accepted and DEFERRED (the engine armed its own submit timer)\n  dropped   — produced a result nobody received, OR matched nothing at all (reason says which)\n  refused   — a gate said no before or at evaluation (the off switch), never \"it vanished\"\nTHE OFF SWITCH IS PART OF THIS VERB: `--off action:<command-id>` or `--off connection:<device>`\nflips a target from the same command that read the rows. `parlay off` / `parlay on` are the direct\nforms; `parlay off status` lists what is off.\nWHAT IS NEVER RECORDED: the evaluated text. A record holds identifiers, verb names, outcome tokens\nand timings — never the string you typed.\nExit codes: 0 ok (including \"this server is too old to have a command log\" — reported, not fatal);\n1 server/runtime error; 2 usage.",
	"off":            "parlay off — turn a CONNECTION or an ACTION off (and 'parlay on' to turn it back on).\nUsage: parlay off <connection|action> <id> [--by <who>] [--surface <name>]\n       parlay off status        (or plain `parlay off`) — what is off right now\n       parlay on  <connection|action> <id>\nTwo targets, two meanings, both real:\n  connection <device-id>   refuse that device's evaluations BEFORE the engine sees the text, and\n                           refuse its pending server-owned fires too. The surface stops being an\n                           action source.\n  action <command-id>      suppress that command's emissions; every other command keeps working.\n                           The id is the engine's own command id (`fired`), the same one\n                           `parlay action-log --input-action` filters on.\nThis is an OPERATIONAL control, not an authorization change: it can only subtract delivery from\nwork the server was already willing to do, and it grants nothing. It is the same server-side state\nthe sandbox page and POST /api/chat/off-switch read and write, so all three surfaces cannot\ndisagree; a flip is refused loudly rather than silently ignored, and turning a target back on is the\nsame call with off:false.\nState is in-memory on the server, deliberately: a mute that survived a restart would be an intent\nthis process cannot confirm it is still honoring.\nExit codes: 0 ok; 1 server/runtime error; 2 usage.",
	"on":             "parlay on — turn a connection or an action back ON.\nUsage: parlay on <connection|action> <id> [--by <who>] [--surface <name>]\nThe exact inverse of `parlay off`: same target, same server-side state, off:false. Idempotent —\nturning on something that is already on reports ON and changes nothing.\nRun `parlay off status` to see what is off.\nExit codes: 0 ok; 1 server/runtime error; 2 usage.",
	"landed":         "parlay landed — the truthful \"did this fix ACTUALLY land?\" proof (robots-0a77).\nUsage: parlay landed <pr> [--repo owner/name] [--branch <remote>/<branch>] [--json]\nThe mechanic contract's proof of landing used to be hand-run as `gh pr view <n> --json state,mergedAt`.\nA BARE gh command does not mean what it reads like: gh's base-repo resolution prefers a remote named\n`upstream` over `origin`, so in a fork clone — which is every clone the fleet works in — it answers about\nthe PARENT project's PR of the same number. Observed live: state=MERGED, mergedAt months earlier, for a\nstranger's PR, while the real PR was still OPEN. That is a false FIXED claim produced by the very command\nthe guardrail prescribed.\nThis verb resolves the repository the way merge-gate does (--repo wins; else the `origin` remote; gh's own\npick only with no usable origin) and asserts BOTH halves of the proof together:\n  1. a git remote in THIS checkout points at the repository being asked about — otherwise the git half and\n     the gh half describe different repositories, which is the defect itself\n  2. GitHub answered about that same repository (not a same-numbered PR elsewhere)\n  3. the PR state is MERGED\n  4. the commit it produced is reachable from the remote base branch — `git branch -r --contains`, run\n     against the resolved remote rather than a hardcoded origin/main\nNeither half alone is enough: (3) alone is the fork defect above, and (4) alone cannot tell a merged PR\nfrom a commit pushed straight to main. Containment is checked for the MERGE commit, not the head sha, so\na squash or rebase merge is proven correctly; the remote is fetched once if the commit is not local yet.\nExit codes: 0 LANDED, 3 NOT-LANDED (the proof ran and failed — do not claim FIXED), 1 gh/git could not\nanswer, 2 usage. Fail-closed in every direction.\nRun it before any FIXED claim: parlay landed 45 || echo NOT-LANDED",
	"variant":        "parlay variant — manage variant agents (isolated git-worktree forks of an existing agent).\nSubcommands:\n  launch <primary-id> [--label <suffix>] [--model MODEL]\n      Fork a primary into a new variant. Creates a git worktree at ~/.parlay/worktrees/<variant-id>.\n      Label defaults to wt1, wt2, … (auto-incremented). Variant id: <primary>-<label>.\n  list [<primary-id>]\n      List all variants, optionally filtered to a specific primary.\n  merge <variant-id>\n      Append novel identity facts + scratchpad notes from the variant into the primary.\n      Deduplicated by content; merged lines tagged [from: <variant-id>]. Idempotent.\n  teardown <variant-id> [--force]\n      Merge insights (unless --force), remove the git worktree, unregister from Parlay,\n      and delete the variant home. Refuses if unmerged insights exist unless --force.",
	"crew-state":     "parlay crew-state — reconcile an agent's keyed status line against parlay's oracle (fold §3.6 Slice 3).\nUsage: parlay crew-state <id>\n  Outputs: <state> · source: <src> · <detail>\n  States: working, done, blocked, needs-decision, paused, failed, resolved, captain-held, unknown.\n  Sources: status (relay confirmed enrollment) | status-degraded (relay unreachable; may be stale)\n           | status-unenrolled (relay does not list the agent) | none (nothing on disk).\n  The on-disk status file always wins over 'unknown': a stale-but-valid state is never discarded,\n  and a FAILED relay lookup is never reported as 'not registered'.\n  Exit codes: 0 state determined; 3 enrolled but no status yet; 4 relay does not list the agent;\n              5 status present but unreadable/unparseable; 6 relay unreachable and no status to fall back on.\n  Env: PARLAY_CREW_READ_BEADS=1 (with PARLAY_CREW_STORE=<beadsDir>) — read the status from the crew\n       bead store instead of the file (status-lift unit 4). Wire output, exit codes, and precedence are\n       identical; any store trouble falls back to the status file. Unset = file read, legacy-identical.",
	"liveness":       "parlay liveness — the FLEET answer to 'which agents are silent, since when, and is the heartbeat absent or merely expired?'.\nUsage: parlay liveness [<agent-id>] [--agent <id>] [--silent-for <dur>] [--silent] [--json]\nOne read-only table over the whole fleet, one row per agent the server or this host knows about:\n  AGENT       the agent id\n  STATE       live    — registered AND a listener process for it is running on this host\n              ghost   — registered with NOTHING listening: a message sent here is spooled for a reader that is gone\n              offline — not in the server's registry at all\n              unknown — the server did not answer, so registration is unknown (NOT the same as offline)\n  HEARTBEAT   the server's own per-channel activity record, and the four shapes it really has:\n              fresh (12s ago) / expired (2h14m ago) — a stamp exists, and only these can expire\n              never observed  — a presence row exists with NO lastSeen: the server has never heard this channel\n              no row          — the snapshot has no row for this channel at all\n              unknown         — the server did not answer, or the stamp does not parse\n  SILENT      how long since the NEWEST dated activity of ANY source (channel record, status file,\n              relay delivery trail), so an agent working without talking is not falsely reported silent.\n              'no' = within the window; a duration = silent beyond it; 'unknown' = no dated record exists.\n  LAST OBSERVED ACTIVITY  which source, what it recorded, and how long ago\nWHY THE COLUMNS ARE SEPARATE: registration is a row nothing removes when a listener dies; the process\ntable is a probe that can FAIL (and a failed probe never becomes 'ghost'); a stamp can expire while an\nempty stamp and an absent row CANNOT — those are absence, not staleness. Collapsing them is what makes\nan operator clear the registration of a working agent.\nFLAGS\n  --silent-for <dur>  the silence window (default 10m; accepts 90s/45m/2h/3d)\n  --silent            only agents whose activity is older than the window, or whose channel has no\n                      heartbeat record at all\n  --agent <id>, or a bare <agent-id>  one agent's row\n  --json              machine-readable; the state/heartbeat/silence vocabularies travel verbatim\nDEGRADED MODES it prints rather than papers over: server unreachable (every state is 'unknown', never\n'offline'); process table unreadable (a listener can be neither confirmed nor ruled out); relay not\nrunning (its delivery trail is a FILE and is still read); no dated record at all ('silence unknown',\nnever 0); an agent with no home on this host (its status file could not be consulted either).\nExit codes: 0 any source answered (even with bad news); 1 NOTHING was observable; 2 usage.\nEnv: PARLAY_SERVER, PARLAY_RELAY_RUNTIME, PARLAY_RELAY_SOCK, PARLAY_AGENT_HOME.\n",
	"timeline":       "parlay timeline — ONE ordered answer to 'what happened', assembled from every durable record the fleet keeps.\nUsage: parlay timeline [<agent-id>] [--agent <id>|--channel <id>] [--since <when>] [--until <when>]\n                      [--outcome <name>[,<name>...]] [--limit <n>] [--json]\nWHERE IT READS (and what each one answers):\n  chat history     {PARLAY_STATE_HOME}/messages.jsonl — the SERVER's own persisted messages, read OFF DISK\n                   (so it answers while the server is down, like the relay's trails). It is the only record\n                   that exists when nothing ever collected a message, which is why a timeline without it\n                   showed silence where the truth was 'the server has it and nobody took it'. Only\n                   id/ts/channel/role/from are read: this reader has no field for a message body, so no\n                   copy of one is made anywhere.\n  delivery ledger  the relay's data-plane trail read OFF DISK ({runtime}/delivery.log + delivery.log.1).\n                   Per-message it says spooled / spool-failed / delivery-ended / rotated. Reading the file\n                   rather than asking the relay is deliberate: the trail still answers while the relay is\n                   dead, which is usually why someone is asking.\n  audit log        {runtime}/audit.log — channel claimed, released, or a takeover refused (who/what/when).\n  relay socket     the live control socket, for the two things only a running relay can say: whether\n                   recording is switched off right now, and WHICH chat server it polls (a relay bound to\n                   another server is named as a warning — its trail does not describe your traffic).\n  command registry GET /api/chat/commands — recent invocations with state, exit code, outcome and timing.\nOUTCOMES (the whole vocabulary — --outcome takes these names):\n  recorded     the chat server persisted this message. NOT a delivery: the relay's hand-over line (if\n               any) is a separate event, and 'recorded' never means anybody took it.\n  unhanded     the server recorded it and the delivery trail — read in full, unrotated, and starting\n               before this message — holds no hand-over for it: NOTHING picked it up. Only stated when\n               absence is evidence; every weaker case stays 'recorded' with the guard that failed.\n  queued       spooled AND the line is still in the spool. There is NO read receipt anywhere in this\n               fleet, so this never means 'delivered' and is never upgraded into one.\n  left-spool   spooled, and the line is no longer in the spool — read or pruned, and nothing records which.\n  dropped      the spool append FAILED: the message never reached the agent.\n  superseded   an earlier hand-over of a message id that was handed over again later (a channel replay).\n  ended        the channel stopped being polled, with the reason and how many lines were still waiting.\n  rotated      the ledger rotated here; everything older than this line is gone.\n  enrolled | retired | refused   relay control-plane actions on a channel.\n  command      one registry invocation (verb → state · exit=N · outcome=T · took=D).\n  unknown      recorded, and this reader cannot classify it — always with the reason.\nTIME: --since/--until take an RFC3339 stamp or a duration back from now (90s, 45m, 2h, 3d). Default is the\nnewest 50 events over the whole trail, oldest first; --limit 0 shows everything.\nHONESTY RULES: a record that could not be read says so in the trailing 'sources' block instead of\ncontributing a healthy-looking zero; an event whose stamp does not parse keeps its row with '?' in the time\ncolumn rather than being dropped; a spool that cannot be read makes its messages 'unknown', never 'gone'; a\nmissing hand-over becomes 'unhanded' only against a delivery trail that is COMPLETE for that message — an\nabsent ledger (an older relay), a rotated or truncated one, a message newer than the relay's poll window, a\nmessage older than the trail's own first line, or an undated one all stay 'recorded', each naming the guard\nthat stopped it.\nDEGRADED MODES it prints: chat history absent (no file in this state dir — the server may run with a\ndifferent -state-dir) or unreadable; a history read of ANOTHER host's state dir while the CLI targets a\nremote server (a warning: those records may be a different server's); a truncated history read (only the\nnewest records, and it says so).\nExit codes: 0 any record answered (even with bad news); 1 NOTHING was observable; 2 usage.\nEnv: PARLAY_SERVER, PARLAY_STATE_HOME, PARLAY_RELAY_RUNTIME, PARLAY_RELAY_SOCK (the same runtime dir the\nmonitor uses).\n",
	"explain":        "parlay explain — ONE agent's whole story in one read, for the 2am question \"why is this agent not answering?\".\nUsage: parlay explain <agent-id>\nRead-only, no flags. Aggregates six sources that each know one slice, and names every source that\ndid not answer instead of silently dropping it:\n  registration   GET /api/chat/subscribers — is it registered, name/color\n  channel        ...the same snapshot's presence row: lastSeen, or 'never observed' (blind vs drifted)\n  crew state     the frozen reconciliation crew-state prints, from the SAME registry read, so the two\n                 surfaces cannot disagree about enrollment\n  status file    the agent's last keyed status line + when it was written\n  pane age       session-start, i.e. how long this pane has been up\n  relay          the relay control socket: up?, WHICH server it polls (registered-but-deaf tell?), and\n                 whether it holds a poll loop for THIS agent\n  queue          the agent's spool file: lines queued and unconfirmed-consumed, and the resume cursor\n                 a monitor restarting here would use (NONE = it would replay the channel backlog)\n  delivery       the relay's durable delivery ledger for this agent (spooled / spool-failed /\n                 delivery-ended / rotated) — what was handed over, never claiming what was read\n  commands       GET /api/chat/commands for this agent: state, timing, exit code, outcome\n  last error     the newest failure any ANSWERING source can see, or 'none observed (looked at: ...)'\nDEGRADED MODES it prints rather than papers over: server unreachable; relay not running (no socket);\nrelay polling a different server than this CLI targets; a spool that exists with no writer; a ledger\nthat was never written, or is switched off, or already rotated (history lossy); a stale vs a missing\nlastSeen; a status file absent vs unreadable vs unparseable.\nExit codes: 0 one or more sources answered (even with bad news — that is the point); 1 NOTHING was\nobservable at all (server silent AND no local record); 2 usage.\nEnv: PARLAY_SERVER, PARLAY_RELAY_RUNTIME, PARLAY_RELAY_SOCK (same runtime-dir resolution the monitor\nuses), PARLAY_AGENT_HOME, PARLAY_CREW_READ_BEADS/PARLAY_CREW_STORE.\n",
	"supervise":      "parlay supervise — wake-on-actionable-status loop with absorb-when-working logic (fold §3.6 Slice 3).\n  Routine verbs (working, paused, resolved, captain-held) are absorbed and only wake if a wedge is detected.\n  Env: PARLAY_UNATTENDED_FLAG — when set to a file path that exists, supervise runs in unattended\n  (away) mode: buffers escalations in a durable queue, detects captain return via in-band marker.\n  Env: PARLAY_CREW_READ_BEADS=1 — scan the per-agent event log (events.jsonl) with a seq cursor\n       (.supervise-seq) instead of the status file's line cursor (status-lift unit 5). Falls back\n       to the line scan while an agent has no event log yet. Unset = line scan, legacy-identical.",
	"status-migrate": "parlay status-migrate — one-shot migration of an agents root onto the bead/event status pipeline (status-lift unit 7).\nUsage: parlay status-migrate --agents-root <dir> [--agent <id>] [--apply] [--live]\n  Replays each agent's existing status lines, in order, into its per-agent events.jsonl and through\n  the same crew-bead fold the live dual-writer uses. REPLAY, NEVER TRUNCATE: the original status\n  file is not modified (a full backup copy status.pre-migrate.bak is written besides), so every\n  legacy consumer keeps working and aborting is free. The supervise cursor (.supervise-seq) is\n  seeded at the log head so history does not re-fire. Unparseable lines are kept in place, never\n  replayed. Agents whose events.jsonl or backup already exists are refused (idempotence latch).\n  --agents-root <dir>  REQUIRED, no default — say exactly which tree you are migrating.\n  --agent <id>         migrate just this agent.\n  --apply              actually migrate; without it, a dry run prints the plan and changes nothing.\n  --live               required on top of --apply to touch the canonical live ~/.parlay/agents —\n                       migrating the captain's production install is captain-gated (robots-lor).\n  Env: PARLAY_CREW_STORE=<beadsDir> (required) — the target bead store, same gate as the dual-writer.\n  Readers stay on the legacy file until PARLAY_CREW_READ_BEADS=1 is set (units 4/5); the intended\n  rollout is migrate -> dual-write shakedown -> flip readers.",
	"sweep":          "parlay sweep — the fleet closure sweep (robots-6xq7): the collector that walks every\nparlay agent store, reads its crew-state, and tears down the ones that are provably finished.\n  Usage: parlay sweep [--apply] [--agent <id>] [--all] [--force] [--interval <sec>] [--verbose]\n  Default is a DRY RUN — it prints the plan and changes nothing.\n  --apply            Actually tear down (each via the same chain 'parlay teardown' runs).\n  --agent <id>       Sweep just this agent; substitutes for the per-task-spawn proof.\n  --all              Drop the per-task-spawn proof fleet-wide (still honors every safety hold).\n  --force            Also sweep agents with no launch spec on disk (implies --all). Their\n                     worktree, if any, is unrecorded and therefore unchecked by teardown —\n                     read the HOLD reason first.\n  --interval <sec>   Loop forever on this cadence (run it alongside robots-watch).\n  --verbose          Also print the quiet skips (agents that are simply still working).\n  Never swept: the sweeping agent itself; ids in $PARLAY_STATE_HOME/sweep-keep; anything in\n  needs-decision/blocked/failed (HELD for the captain — a teardown would destroy what he needs\n  to read). A done agent with uncommitted or unlanded work is refused by teardown, not forced.",
	"stale":          "parlay stale — the stale-window detector (robots-9d2w): is this pane worth SENDING to, or\nshould it be relaunched? A finished agent is still registered, still enrolled, and still accepts\nmessages — so a re-task lands in a session whose transcript is entirely the job it already closed,\nand every turn of the new work re-pays for it (the captain caught one at 70% context whose own\nharness was offering \"/clear to save 141.4k tokens\").\n  Usage: parlay stale <agent-id> [--quiet]\n  Exit 0 FRESH — continue it. Exit 3 STALE — relaunch instead. Exit 2 usage.\n  Exit 3 matches 'context-check' (ROTATE): the same call from the other side of the pane.\n  --quiet   exit code only, no output (for scripts).\nSTALE means a terminal status verb (done/failed) on an enrolled agent — it stopped and is sitting at\nits prompt. Deliberately NOT stale: needs-decision/blocked/paused (waiting on a reply — a message is\nthe intended unblock), working, and unknown (fail-open: a relay hiccup must never become a refused\nsend). Ids on $PARLAY_STATE_HOME/sweep-keep are never stale — that list is already sweep's escape\nhatch for long-lived agents that ARE re-tasked in place.\nRead-only: it never tears down, spawns, or sends. Closing a stale window is 'parlay sweep --apply'.\n'parlay send' runs this check itself and refuses a stale target; --force waives it.",
	"teardown":       "parlay teardown — safe destroy of an agent with an isolated worktree (fold §3.7 Slice 3).\n  Refuses to remove agents that have uncommitted changes or unpushed commits not yet landed.\n  Validates landed-content containment with one check: merge-tree tree-OID equality against the\n  default branch (catches squash-merged work). No PR/patch-id check exists — inconclusive means refuse.\n  Usage: parlay teardown <id> [--force]\n  --force   Override refusal and discard unlanded work.\n  Steps: (1) check git status, (2) validate unpushed commits are landed, (3) deregister from relay,\n  (4) remove worktree, (5) delete agent store.",
	"guard":          "parlay guard — runtime worktree-tangle + watcher-liveness alarm (ported from firstmate fm-guard.sh, AGENTS.md §8).\nParlay's isolation primitive is 'parlay variant' (a linked worktree at ~/.parlay/worktrees/<id>). The tangle failure\nmode is a parlay agent branching/committing in the PRIMARY checkout instead of its own variant worktree, stranding\nthe primary on a feature branch. This is the RUNTIME backstop for that — the brief/enrollment prose is only the\nupstream assertion. WARNS, never BLOCKS: always exits 0 (usage errors exit 2).\nUsage: parlay guard [--repo <path>] [--grace <sec>] [--read-only] [--json]\n       parlay guard --beat [--json]\n  --repo <path>   primary checkout to check (default: cwd's git toplevel)\n  --grace <sec>   watcher-liveness grace window (default 300)\n  --read-only     advisory phrasing — leave restore/repair to the session holding the fleet lock\n  --beat          touch the liveness beacon and exit (a live watcher/monitor calls this each poll cycle)\n  --json          machine-readable status\nChecks: (1) TANGLE — primary checkout on a NAMED non-default branch → bordered banner naming the branch + a\nnon-destructive 'git checkout <default>' restore (the branch ref is kept). Detached HEAD (linked worktrees) never\ntrips it. (2) LIVENESS — with variants in flight, a missing/stale beacon → 'WATCHER DOWN' banner.\nBeacon: $PARLAY_STATE_HOME/guard/.last-watcher-beat (default ~/.parlay/…).",
	"lavish-import":  "parlay lavish-import — import lavish sessions via the bundled importer.\nUsage: parlay lavish-import",
	"context-check":  "parlay context-check — machine-readable rotation advisory for persistent agents.\nUsage: parlay context-check <pct> [--threshold <pct>]\n  <pct>              your current context usage (0–100). Accepts 85, 85%, or 0.85. YOU pass what\n                     your harness knows — Claude Code exposes no context gauge to a CLI.\n  --threshold <pct>  rotate at/above this (default 85).\nOutput + exit codes (scriptable): below → 'OK <pct>% (threshold <t>%)', exit 0;\n  at/above → 'ROTATE: …', exit 3; bad pct → exit 2. The ROTATE line names the next step, which differs by\n  machine: it offers the federation-store recipe where the `handoff` wrapper is installed, and the\n  portable substitute everywhere else.\nRotation loop: on ROTATE, write the handoff, then 'identity --submit' (atomic — see identity --help).\n  'identity --submit' needs a handoff id. It auto-resolves one only where the `handoff` store wrapper is\n  installed (it ships with the author's federation tooling, NOT with parlay); with no store, pass any id\n  explicitly — 'parlay drawdown' drafts the body from history and needs nothing either. Example:\n    parlay context-check 87 || parlay drawdown 20      # store-agnostic: drafts the body either way\n  The supervisor-respawn side lives in GasCity.",
	"robots-watch":   "parlay robots-watch — MVP event poll-daemon (decision-4zr interim bridge).\nPolls each watched store's '<store> list --all --json', diffs a persisted per-bead status cursor, and routes each\n(store, status-change) through a handler table. Stands in for the not-yet-built beads EMIT hook (task-n1ao);\nswap the poll source for the ingest endpoint later and the router/handlers are unchanged.\nUsage: parlay robots-watch [--interval <sec>] [--once] [--verbose]\n  --interval <sec>  poll cadence (default 15; ignored with --once)\n  --once            single poll pass then exit (tests / cron)\n  --verbose         log every pass + routed event to stderr\nHandlers:\n  (a) robots bead CREATED          → mechanic-dispatch <id> (idempotent)\n  (a2) inbox bead CREATED           → inbox-dispatch <id> (idempotent)\n  (b) inbox/request/question/task CLOSED → notify the requester channel from the bead's 'notify:<channel>' label\n                                      via 'parlay send --<channel>'\nState: $PARLAY_STATE_HOME/robots-watch/cursor.json (default ~/.parlay/…). First sighting of a store SEEDS its\ncursor and fires nothing; only transitions observed AFTER seeding fire handlers. Run under launchd for the daemon.",
	"robots-tail":    "parlay robots-tail — PUSH fast path (task-jif2): byte-offset tailer of the robots events stream → mechanic-dispatch.\nModeled on the server hook-tailer: every ~1s it reads only the bytes past a persisted offset in\n$ROBOTS_EVENTS_FILE (default ~/data/robots/events.jsonl, appended by the robots create-emit wrapper), parses each\nnew line for a robots bead id, and calls mechanic-dispatch <id> (idempotent) immediately — sub-~1s create→dispatch.\nUsage: parlay robots-tail [--once] [--verbose]\n  --once      one tail pass from the persisted offset, then exit (tests / cron)\n  --verbose   log skipped lines\nFirst-ever run starts at EOF (no history replay); the persisted offset ($PARLAY_STATE_HOME/robots-watch/tail-offset)\nresumes across restarts. The poll daemon 'robots-watch' stays the reconciler fallback for any missed emit;\nmechanic-dispatch idempotency makes a double-fire from both paths safe. Run both under launchd.",
	"inbox-tail":     "parlay inbox-tail — PUSH fast path for the inbox store: byte-offset tailer of the inbox events stream → inbox-dispatch.\nMirrors robots-tail: every ~1s it reads only the bytes past a persisted offset in\n$INBOX_EVENTS_FILE (default ~/data/inbox/events.jsonl, appended by the inbox create-emit wrapper), parses each\nnew line for an inbox bead id, and calls inbox-dispatch <id> (idempotent) immediately — sub-~1s create→dispatch.\nUsage: parlay inbox-tail [--once] [--verbose]\n  --once      one tail pass from the persisted offset, then exit (tests / cron)\n  --verbose   log skipped lines\nFirst-ever run starts at EOF (no history replay); the persisted offset ($PARLAY_STATE_HOME/robots-watch/inbox-tail-offset)\nresumes across restarts. The poll daemon 'robots-watch' (handler a2) stays the reconciler fallback for any missed emit;\ninbox-dispatch idempotency makes a double-fire from both paths safe. Run both under launchd.",
	"eval":           "parlay eval — the compiled string-evaluation engine (voice layer), unified into the parlay binary.\nUsage: parlay eval serve [--addr <host:port>] [--push-url <url>]\n  serve   Run the eval-engine HTTP service in the foreground until killed.\n          Endpoints: POST /eval (hot path), GET /stats, GET /commands, GET /health.\n          --addr wins over PARLAY_EVAL_ADDR (default 127.0.0.1:4343 — a HOST-WIDE\n            slot shared by every parlay instance on the machine; the engine has no state dir\n            and no config key, so its address is its identity);\n          --push-url wins over PARLAY_EVAL_PUSH_URL (default\n            http://127.0.0.1:4242/api/chat/eval-push — the DEFAULT server, so an engine\n            started for a second instance must point this at that instance or it drives the\n            first instance's panel. The CLI probes the engine at PARLAY_EVAL_ENGINE_URL.)\nManifest: PARLAY_COMMANDS file, or a commands.json next to the binary, over the embedded\ndefault — fs-watched, fail-closed hot-reload.\nFormerly the standalone packages/eval-engine binary (parlay-eval-engine); the engine now\nlives in tools/cli/internal/evalengine and ships in this one binary.",
	"mechanic":       "parlay mechanic — kill switch for the robots→mechanic auto-spawner.\nPause or resume automatic mechanic dispatch with one command — no launchd fiddling, no killing the tailer.\nUsage: parlay mechanic off            create the sentinel file; dispatch is silenced immediately\n       parlay mechanic on             remove the sentinel file; dispatch resumes for NEW beads\n       parlay mechanic status         print on|off, the reason, and the resolved sentinel path\nDisabled state = presence of $PARLAY_STATE_HOME/mechanic-dispatch.off (default ~/.parlay/mechanic-dispatch.off),\nOR env PARLAY_MECHANIC_DISPATCH=off. Both trigger paths (robots-tail PUSH and robots-watch POLL) respect the gate.\nPrecedence: PARLAY_MECHANIC_DISPATCH=off forces off (wins over a missing sentinel);\nPARLAY_MECHANIC_DISPATCH=on does NOT force-enable past a present sentinel — the sentinel is the\ndurable operator intent and wins. When OFF, the tailer and poller continue running and advancing\ntheir offsets normally; only the spawn is skipped, so re-enabling does NOT replay the backlog.",
	"inbox-dispatch": "parlay inbox-dispatch — kill switch for the inbox→handler auto-dispatcher.\nPause or resume automatic INBOX dispatch with one command — no launchd fiddling, no killing the watcher.\nUsage: parlay inbox-dispatch off      create the sentinel; dispatch is silenced immediately\n       parlay inbox-dispatch on       remove the sentinel; dispatch resumes for NEW beads\n       parlay inbox-dispatch status   print on|off, the reason, and the resolved sentinel path\nDisabled state = presence of $PARLAY_STATE_HOME/inbox-dispatch.off (default ~/.parlay/inbox-dispatch.off),\nOR env PARLAY_INBOX_DISPATCH=off. Both trigger paths (inbox-tail PUSH and robots-watch POLL handler a2)\nrespect the gate. PARLAY_INBOX_DISPATCH=off forces off; PARLAY_INBOX_DISPATCH=on does NOT force-enable\npast a present sentinel — the sentinel is the durable operator intent and wins. When OFF the tailer and\npoller keep running and advancing their offsets; only the spawn is skipped, so re-enabling does NOT\nreplay the backlog.\nINDEPENDENT of 'parlay mechanic': pausing inbox dispatch leaves robots→mechanic dispatch running, and\nvice versa. They read different sentinels and different env vars.",
}

// Aliases maps every alternative spelling the dispatcher accepts to the
// canonical verb whose help text answers for it.
//
// The handlers already route an alias to its canonical command before asking
// for help (`parlay reply --help` prints say's text), so this map does not
// change what any verb prints today — it makes that relationship declared
// rather than implied, so Lookup("reply") is correct for any caller that asks
// by the name a user typed, and so the alias set can be pinned by a test
// instead of drifting one handler at a time.
var Aliases = map[string]string{
	"agent-up":    "listen",
	"reincarnate": "reset",
	"reply":       "say",
}

// Lookup returns the help text for cmd, or ok=false if there is none registered.
// An alias resolves to its canonical verb's text.
func Lookup(cmd string) (string, bool) {
	if canonical, ok := Aliases[cmd]; ok {
		cmd = canonical
	}
	t, ok := HELP[cmd]
	return t, ok
}

// Wanted checks argv for --help/-h; if present, prints cmd's help text (or
// the full USAGE if cmd has none registered) and returns true — matching
// help.ts's helpWanted(). Callers return immediately when this is true.
func Wanted(cmd string, argv []string) bool {
	asked := false
	for _, a := range argv {
		if a == "--help" || a == "-h" {
			asked = true
			break
		}
	}
	if !asked {
		return false
	}
	if text, ok := HELP[cmd]; ok {
		fmt.Println(text)
	} else {
		fmt.Println(Usage(config.ServerURL()))
	}
	return true
}
